import numpy as np, warnings; warnings.filterwarnings("ignore")
from hera.analysis import open_run, sdh_onset
for rid, blo in [(6, 0.85), (6, 1.0), (7, 0.75)]:
    r = open_run(f"data/{rid}"); B = r.col("magnet_field"); R = r.col("sr1_X") / (r.col("sr0_X") / -1e6)
    o = np.argsort(B); B, R = B[o], R[o]
    on = sdh_onset(R, B, b_lo=blo, r_full_scale=50e-6/9.9e-9)
    print(f"--- run {rid} b_lo {blo}"); print(on.summary())
    if rid == 6 and blo == 1.0:
        for b in (0.5, 1, 2, 5, 8, 10):
            i = np.argmin(abs(B - b)); print(f"   R({b} T) = {np.median(R[max(0,i-3):i+3]):.1f} Ohm")
EOF

